// Valider les parametres
const input = $input.first().json;
const query = input.query || {};

const projectId = query.project_id || null;
const discordUserId = query.discord_user_id || null;

const errors = [];
if (!projectId) errors.push('project_id');
if (!discordUserId) errors.push('discord_user_id');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: projectId,
    discord_user_id: discordUserId
  }
}];

// Verifier si le subscriber existe et formater la reponse
const dbResults = $input.all();
const inputData = $('Validate Input').first().json;

if (!dbResults || dbResults.length === 0 || !dbResults[0].json.id) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Aucun abonnement trouve pour discord_user_id '${inputData.discord_user_id}' dans le projet '${inputData.project_id}'`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

const subscriber = dbResults[0].json;

// Calculer le pourcentage d'utilisation
const creditsUsed = (subscriber.credits_total || 0) - (subscriber.credits_remaining || 0);
const usagePercent = subscriber.credits_total > 0 
  ? Math.round((creditsUsed / subscriber.credits_total) * 100) 
  : 0;

return [{
  json: {
    found: true,
    subscriber: {
      id: subscriber.id,
      project_id: subscriber.project_id,
      discord_user_id: subscriber.discord_user_id,
      email: subscriber.email,
      plan_id: subscriber.plan_id,
      stripe_customer_id: subscriber.stripe_customer_id,
      stripe_subscription_id: subscriber.stripe_subscription_id,
      credits_remaining: subscriber.credits_remaining || 0,
      credits_total: subscriber.credits_total || 0,
      credits_used: creditsUsed,
      usage_percent: usagePercent,
      subscription_status: subscriber.subscription_status || 'unknown',
      current_period_start: subscriber.current_period_start,
      current_period_end: subscriber.current_period_end,
      created_at: subscriber.created_at,
      updated_at: subscriber.updated_at
    }
  }
}];
